import assert from 'node:assert/strict';import {chromium} from 'playwright-core';
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--disable-gpu','--no-first-run']});const page=await browser.newPage({viewport:{width:1600,height:980}});const errors=[];page.on('pageerror',e=>errors.push(e.message));
try{await page.goto('http://127.0.0.1:5974/?desktop=1&engine=clothcraft&testSession=global-bottom-20261028',{waitUntil:'domcontentloaded'});await page.locator('.main-layout').waitFor();const output=[];
for(const mode of ['split','2d']){await page.getByRole('combobox',{name:'3D and 2D window arrangement'}).selectOption(mode);const host=page.locator('.main-layout>.exo-global-grade-dock-host');await host.waitFor({state:'visible',timeout:12000});for(const [kind,name] of [['values','Grading Table'],['compare','Compare Length']]){await page.evaluate(command=>window.dispatchEvent(new CustomEvent('exo-clothcraft-pattern-studio-command',{detail:{command}})),kind==='values'?'grade-table':'grade-compare');await page.locator(`.exo-grade-bottom-widget[data-exo-grade-bottom-widget="${kind}"] .exo-grade-widget-placement`).selectOption('bottom');}
await page.waitForTimeout(180);const data=await page.evaluate(()=>{const root=document.querySelector('.main-layout'),host=root.querySelector(':scope>.exo-global-grade-dock-host'),widgets=[...host.querySelectorAll('.exo-grade-bottom-widget--docked')],els=['.asset-browser','.tool-rail','.workspaces','.clo-inspector'].map(s=>root.querySelector(s));const r=e=>e.getBoundingClientRect().toJSON();return{host:r(host),root:r(root),widgets:widgets.map(w=>({name:w.dataset.exoGradeBottomWidget,rect:r(w)})),parts:els.map(r),occupied:host.dataset.exoGradeDockOccupied}});assert.equal(data.widgets.length,2,JSON.stringify(data));assert(data.host.width>=data.root.width-2);for(const panel of data.parts)assert(panel.bottom<=data.host.top+3,`panel extends below dock ${JSON.stringify(data)}`);assert(data.host.height>=190);output.push({mode,hostWidth:data.host.width,hostHeight:data.host.height,widgets:data.widgets.map(w=>w.name)});for(const [kind,name] of [['values','Grading Table'],['compare','Compare Length']])await host.locator(`[data-exo-grade-bottom-widget="${kind}"]`).getByRole('button',{name:`Close ${name}`}).click();}
assert.equal(errors.length,0,errors.join('; '));console.log(JSON.stringify({ok:true,output},null,2));}finally{await browser.close()}
